"use client";
import { motion, useReducedMotion } from "motion/react";
import { type CSSProperties, type ReactNode, useRef, useState } from "react";
import { useControlDialog } from "../controls/control-shared";
import { MenuInternalStyles, useMenuState } from "./menu-shared";
export interface FullscreenSlideMenuLink {
  id: string;
  label: string;
  href: string;
  image?: string;
  imageAlt?: string;
}
export interface FullscreenSlideMenuProps {
  links: readonly FullscreenSlideMenuLink[];
  secondaryLinks?: readonly FullscreenSlideMenuLink[];
  children: ReactNode;
  brand?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onNavigate?: (link: FullscreenSlideMenuLink) => void;
  duration?: number;
  background?: string;
  color?: string;
  className?: string;
  style?: CSSProperties;
}
export function FullscreenSlideMenu({
  links,
  secondaryLinks = [],
  children,
  brand = "Studio",
  open,
  defaultOpen = false,
  onOpenChange,
  onNavigate,
  duration = 0.9,
  background = "#111",
  color = "#f0f0ed",
  className,
  style,
}: FullscreenSlideMenuProps) {
  const [expanded, setExpanded] = useMenuState(open, defaultOpen, onOpenChange),
    [active, setActive] = useState(links[0]?.id);
  const trigger = useRef<HTMLButtonElement>(null),
    reduced = useReducedMotion();
  const initiallyOpen = useRef(open ?? defaultOpen);
  const dialog = useControlDialog(expanded, setExpanded, duration, trigger);
  const transition = {
    duration: reduced ? 0 : duration,
    ease: [0.76, 0, 0.24, 1] as [number, number, number, number],
  };
  const navigate = (link: FullscreenSlideMenuLink) => {
    setExpanded(false);
    onNavigate?.(link);
  };
  const buttonStyle: CSSProperties = {
    display: "flex",
    gap: 18,
    alignItems: "center",
    minHeight: 44,
    fontSize: 16,
    padding: "8px 0",
  };
  return (
    <div
      data-fullscreen-slide-menu
      className={`z-am-animated ${className ?? ""}`}
      style={{ position: "relative", isolation: "isolate", overflow: "hidden", ...style }}
    >
      <MenuInternalStyles />
      <motion.div
        data-slide-page
        inert={expanded}
        initial={false}
        animate={{
          y: expanded ? "35%" : "0%",
          rotate: expanded ? 8 : 0,
          scale: expanded ? 0.85 : 1,
        }}
        transition={transition}
        style={{
          transformOrigin: "center bottom",
          minHeight: "var(--zeus-animation-height,480px)",
        }}
      >
        {children}
      </motion.div>
      <header
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          padding: "20px 32px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          color,
        }}
      >
        <span style={{ fontSize: 14 }}>{brand}</span>
        <button
          ref={trigger}
          type="button"
          className="z-am-reset"
          style={buttonStyle}
          aria-expanded={expanded}
          aria-label="Open navigation menu"
          onClick={() => setExpanded(true)}
        >
          Menu{" "}
          <span aria-hidden style={{ fontSize: 25 }}>
            ☰
          </span>
        </button>
      </header>
      <dialog
        ref={dialog}
        open={initiallyOpen.current || undefined}
        aria-label="Navigation"
        onKeyDown={(event) => {
          if (event.key !== "Tab") return;
          const controls = [
            ...event.currentTarget.querySelectorAll<HTMLElement>(
              'a[href],button:not([disabled]),[tabindex="0"]',
            ),
          ].filter((node) => node.getClientRects().length);
          const first = controls[0],
            last = controls.at(-1);
          if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last?.focus();
          } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first?.focus();
          }
        }}
        style={{
          position: "fixed",
          inset: 0,
          margin: 0,
          border: 0,
          padding: 0,
          width: "100vw",
          height: "100dvh",
          maxWidth: "none",
          maxHeight: "none",
          overflow: "hidden",
          background: "transparent",
          color,
        }}
      >
        <style>{`[data-fullscreen-slide-menu] dialog::backdrop{background:transparent}`}</style>
        <motion.div
          data-slide-menu-surface
          initial={false}
          animate={{ y: expanded ? "0%" : "-105%", rotate: expanded ? 0 : -8 }}
          transition={transition}
          style={{
            position: "absolute",
            inset: 0,
            background,
            transformOrigin: "left bottom",
            overflow: "auto",
          }}
        >
          <header
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              zIndex: 3,
              padding: "20px 32px",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <span style={{ fontSize: 14 }}>{brand}</span>
            <button
              type="button"
              className="z-am-reset"
              style={buttonStyle}
              aria-label="Close navigation menu"
              onClick={() => setExpanded(false)}
            >
              Close{" "}
              <span aria-hidden style={{ fontSize: 32 }}>
                ×
              </span>
            </button>
          </header>
          <div className="z-am-fs-layout">
            <nav
              aria-label="Full navigation"
              style={{ display: "flex", flexDirection: "column", alignItems: "flex-start" }}
            >
              {links.map((link, index) => (
                <motion.a
                  key={link.id}
                  className="z-am-reset"
                  href={link.href}
                  onClick={() => navigate(link)}
                  onPointerEnter={() => setActive(link.id)}
                  onFocus={() => setActive(link.id)}
                  initial={false}
                  animate={{ y: expanded ? 0 : 45, opacity: expanded ? 1 : 0 }}
                  transition={{
                    ...transition,
                    delay: expanded && !reduced ? 0.2 + index * 0.06 : 0,
                  }}
                  style={{
                    fontSize: "clamp(38px,5vw,72px)",
                    fontWeight: 550,
                    letterSpacing: "-.045em",
                    lineHeight: 1.25,
                  }}
                >
                  {link.label}
                </motion.a>
              ))}
              <div style={{ display: "flex", flexDirection: "column", marginTop: 32, gap: 4 }}>
                {secondaryLinks.map((link) => (
                  <a
                    key={link.id}
                    href={link.href}
                    className="z-am-reset"
                    onClick={() => navigate(link)}
                    style={{ minHeight: 36, fontSize: 14, opacity: 0.65 }}
                  >
                    {link.label}
                  </a>
                ))}
              </div>
            </nav>
            <div style={{ position: "relative", minWidth: 0 }}>
              {links
                .filter((link) => link.image)
                .map((link, index) => (
                  <motion.img
                    key={link.id}
                    src={link.image}
                    alt={link.imageAlt ?? ""}
                    className="z-am-fs-picture"
                    initial={false}
                    animate={{
                      opacity: active === link.id ? 1 : 0,
                      scale: active === link.id ? 1 : 1.04,
                    }}
                    transition={{ duration: reduced ? 0 : 0.45 }}
                    style={{
                      display: "block",
                      position: index === 0 ? "relative" : "absolute",
                      inset: 0,
                    }}
                    aria-hidden={active !== link.id}
                  />
                ))}
            </div>
          </div>
        </motion.div>
      </dialog>
    </div>
  );
}
